//! 文件系统操作服务: 提供前端 Tauri fs 插件缺失的递归目录复制能力。

use std::{fs, path::Path};

/// 递归复制目录 `source` 到 `destination`。
///
/// * 目标目录不存在时自动创建;
/// * 已存在的文件会被覆盖 (目录则合并)。
#[tauri::command]
pub async fn copy_directory(source: String, destination: String) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        let src = Path::new(&source);
        let dst = Path::new(&destination);
        if !src.is_dir() {
            return Err("源路径不是目录".to_string());
        }
        copy_dir_recursive(src, dst).map_err(|e| e.to_string())
    })
    .await
    .map_err(|e| e.to_string())?
}

fn copy_dir_recursive(source: &Path, destination: &Path) -> std::io::Result<()> {
    fs::create_dir_all(destination)?;

    for entry in fs::read_dir(source)? {
        let entry = entry?;
        let source_path = entry.path();
        let destination_path = destination.join(entry.file_name());

        if entry.file_type()?.is_dir() {
            copy_dir_recursive(&source_path, &destination_path)?;
        } else {
            if let Some(parent) = destination_path.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::copy(&source_path, &destination_path)?;
        }
    }

    Ok(())
}
